CREATE TABLE users (id uniqueidentifier PRIMARY KEY, email nvarchar(255) NOT NULL UNIQUE, password_hash nvarchar(max) NOT NULL, role nvarchar(20) NOT NULL DEFAULT 'student' CHECK(role IN ('student','expert','admin')), profile_completed bit NOT NULL DEFAULT 0, created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE profiles (user_id uniqueidentifier PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, full_name nvarchar(255) NOT NULL, birth_date date, gender nvarchar(30), phone nvarchar(30), school_class nvarchar(50), emergency_contact nvarchar(max));
CREATE TABLE family_members (id uniqueidentifier PRIMARY KEY, user_id uniqueidentifier NOT NULL REFERENCES users(id) ON DELETE CASCADE, full_name nvarchar(255) NOT NULL, birth_date date NOT NULL, identity_number nvarchar(30), phone nvarchar(30) NOT NULL, created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE experts (id uniqueidentifier PRIMARY KEY, user_id uniqueidentifier NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, specialty nvarchar(255) NOT NULL, bio nvarchar(max), years_experience int NOT NULL DEFAULT 0, verified bit NOT NULL DEFAULT 0);
CREATE TABLE surveys (id uniqueidentifier PRIMARY KEY, code nvarchar(50) NOT NULL, version nvarchar(20) NOT NULL, name nvarchar(255) NOT NULL, description nvarchar(max), active bit NOT NULL DEFAULT 1, CONSTRAINT UQ_surveys_code_version UNIQUE(code,version));
CREATE TABLE survey_questions (id uniqueidentifier PRIMARY KEY, survey_id uniqueidentifier NOT NULL REFERENCES surveys(id) ON DELETE CASCADE, position int NOT NULL, prompt nvarchar(max) NOT NULL, dimension nvarchar(50), options nvarchar(max) NOT NULL, CONSTRAINT UQ_survey_questions_position UNIQUE(survey_id,position));
CREATE TABLE survey_attempts (id uniqueidentifier PRIMARY KEY, user_id uniqueidentifier NOT NULL REFERENCES users(id) ON DELETE CASCADE, survey_id uniqueidentifier NOT NULL REFERENCES surveys(id), started_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), completed_at datetime2);
CREATE TABLE survey_answers (id uniqueidentifier PRIMARY KEY, attempt_id uniqueidentifier NOT NULL REFERENCES survey_attempts(id) ON DELETE CASCADE, question_id uniqueidentifier NOT NULL REFERENCES survey_questions(id), value int NOT NULL CHECK(value BETWEEN 0 AND 3));
CREATE TABLE assessment_results (id uniqueidentifier PRIMARY KEY, attempt_id uniqueidentifier NOT NULL UNIQUE REFERENCES survey_attempts(id) ON DELETE CASCADE, user_id uniqueidentifier NOT NULL REFERENCES users(id), score int NOT NULL, level nvarchar(50) NOT NULL, breakdown nvarchar(max) NOT NULL, interpretation nvarchar(max), source nvarchar(30) NOT NULL DEFAULT 'survey', created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE appointments (id uniqueidentifier PRIMARY KEY, user_id uniqueidentifier NOT NULL REFERENCES users(id), expert_id uniqueidentifier NULL REFERENCES experts(id), expert_name nvarchar(255) NOT NULL, scheduled_at datetime2 NOT NULL, mode nvarchar(20) NOT NULL, status nvarchar(20) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','completed','cancelled')), notes nvarchar(max));
CREATE TABLE assistant_conversations (id uniqueidentifier PRIMARY KEY, user_id uniqueidentifier NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE assistant_messages (id uniqueidentifier PRIMARY KEY, conversation_id uniqueidentifier NOT NULL REFERENCES assistant_conversations(id) ON DELETE CASCADE, role nvarchar(20) NOT NULL, content nvarchar(max) NOT NULL, created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE sos_requests (id uniqueidentifier PRIMARY KEY, user_id uniqueidentifier NULL REFERENCES users(id) ON DELETE SET NULL, status nvarchar(20) NOT NULL DEFAULT 'open' CHECK(status IN ('open','acknowledged','resolved')), payload nvarchar(max), created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), resolved_at datetime2);
CREATE INDEX IX_assessment_results_user_created ON assessment_results(user_id,created_at DESC);
CREATE INDEX IX_appointments_user_scheduled ON appointments(user_id,scheduled_at);
CREATE INDEX IX_sos_requests_status_created ON sos_requests(status,created_at DESC);
